tool_input.command:
mkdir -p migrations/down && cat > migrations/002_webhook_events.sql <<'EOF'
-- Payment webhook events already handled; the primary key makes a redelivered event a no-op.
create table webhook_events (
  id text primary key,
  type text not null,
  payment_id text not null,
  created bigint not null,
  received_at timestamptz not null default now()
);

-- Unix time of the webhook event that last set orders.status (null: status not set by a webhook).
alter table orders add column status_event_at bigint;
EOF
cat > migrations/down/002_webhook_events.sql <<'EOF'
alter table orders drop column status_event_at;
drop table webhook_events;
EOF
python3 - <<'EOF'
p='src/app.ts'
s=open(p).read()
s=s.replace('import { pool } from "./db.ts";','import { createHmac, timingSafeEqual } from "node:crypto";\nimport { pool } from "./db.ts";\nimport { webhookSecret } from "./payments.ts";',1)
s=s.replace('''  app.use(express.json());
''','''  app.use(express.json({ verify: (req, _res, buf) => { (req as Request).rawBody = buf; } }));
''',1)
s=s.replace('''  app.use(auth);
''','''  // Called by the payment provider, so it is authenticated by signature, not by user token.
  app.post("/webhooks/payments", async (req, res) => {
    const signature = req.headers["provider-signature"];
    const raw = req.rawBody;
    if (typeof signature !== "string" || !raw) return sendError(res, 401, "invalid_signature", "Invalid signature");
    const expected = createHmac("sha256", webhookSecret).update(raw).digest();
    const given = Buffer.from(signature, "hex");
    if (given.length !== expected.length || !timingSafeEqual(given, expected)) {
      return sendError(res, 401, "invalid_signature", "Invalid signature");
    }

    const { id, type, paymentId, created } = req.body ?? {};
    const target = typeof type === "string" ? EVENT_STATUS[type] : undefined;
    if (typeof id !== "string" || !id || typeof paymentId !== "string" || !paymentId || !Number.isInteger(created) || !target) {
      return sendError(res, 400, "invalid_event", "Invalid event");
    }

    const client = await pool.connect();
    try {
      await client.query("begin");
      const fresh = await client.query(
        "insert into webhook_events (id, type, payment_id, created) values ($1, $2, $3, $4) on conflict do nothing",
        [id, type, paymentId, created],
      );
      if (fresh.rowCount === 0) {
        await client.query("rollback");
        return res.json({ ok: true, duplicate: true });
      }
      const { rows } = await client.query(
        "select id, status, status_event_at from orders where payment_id = $1 for update",
        [paymentId],
      );
      if (rows.length === 0) {
        // Not recorded, so the provider's retry is processed once the order has its payment id.
        await client.query("rollback");
        return sendError(res, 404, "not_found", "Order not found");
      }
      const order = rows[0];
      // Never move an order back: refunded is final, failed/paid only come from pending, and a
      // later successful retry may replace an older failure.
      const allowed =
        (target === "paid" && (order.status === "pending" || (order.status === "failed" && created > Number(order.status_event_at ?? 0)))) ||
        (target === "failed" && order.status === "pending") ||
        (target === "refunded" && (order.status === "pending" || order.status === "paid"));
      if (allowed) {
        await client.query("update orders set status = $2, status_event_at = $3 where id = $1", [order.id, target, created]);
      }
      await client.query("commit");
      res.json({ ok: true, applied: allowed });
    } catch (err) {
      await client.query("rollback").catch(() => {});
      throw err;
    } finally {
      client.release();
    }
  });

  app.use(auth);
''',1)
s=s.replace('''export function sendError''','''declare module "http" {
  interface IncomingMessage {
    rawBody?: Buffer;
  }
}

const EVENT_STATUS: Record<string, string | undefined> = Object.assign(Object.create(null), {
  "charge.succeeded": "paid",
  "charge.failed": "failed",
  "charge.refunded": "refunded",
});

export function sendError''',1)
open(p,'w').write(s)
EOF
sed -n 60,200p test/app.test.ts; grep -n "pay_\|orders" db/seed.sql

cat >> test/app.test.ts <<'EOF'

const sign = (body: string) => createHmac("sha256", webhookSecret).update(body).digest("hex");
const hook = (event: object, signature?: string) => {
  const body = JSON.stringify(event);
  return fetch(`${base}/webhooks/payments`, {
    method: "POST",
    headers: { "content-type": "application/json", "provider-signature": signature ?? sign(body) },
    body,
  });
};
const statusOf = async (paymentId: string) =>
  (await pool.query("select status from orders where payment_id = $1", [paymentId])).rows[0].status;
const newOrder = async (paymentId: string, status = "pending") => {
  await pool.query("insert into orders (user_id, status, total_cents, payment_id) values (1, $1, 100, $2)", [status, paymentId]);
};

test("webhook rejects bad signatures and bad events", async () => {
  await newOrder("pay_w1");
  const event = { id: "evt_bad1", type: "charge.succeeded", paymentId: "pay_w1", created: 1000 };
  assert.equal((await hook(event, "00")).status, 401);
  assert.equal((await hook(event, "ab".repeat(32))).status, 401);
  assert.equal((await hook({ ...event, type: "charge.weird" })).status, 400);
  assert.equal((await hook({ ...event, created: "x" })).status, 400);
  assert.equal((await hook({ ...event, paymentId: "pay_missing" })).status, 404);
  assert.equal(await statusOf("pay_w1"), "pending");
});

test("webhook sets paid then refunded; duplicates and late events do not move it back", async () => {
  await newOrder("pay_w2");
  const ok = { id: "evt_w2a", type: "charge.succeeded", paymentId: "pay_w2", created: 1000 };
  assert.equal((await hook(ok)).status, 200);
  assert.equal(await statusOf("pay_w2"), "paid");
  assert.equal((await (await hook(ok)).json()).duplicate, true);
  await hook({ id: "evt_w2b", type: "charge.refunded", paymentId: "pay_w2", created: 1001 });
  assert.equal(await statusOf("pay_w2"), "refunded");
  await hook({ id: "evt_w2c", type: "charge.succeeded", paymentId: "pay_w2", created: 999 });
  await hook({ id: "evt_w2d", type: "charge.failed", paymentId: "pay_w2", created: 1002 });
  assert.equal(await statusOf("pay_w2"), "refunded");
});

test("webhook: failure then newer success is paid; failure after success is ignored", async () => {
  await newOrder("pay_w3");
  await hook({ id: "evt_w3a", type: "charge.failed", paymentId: "pay_w3", created: 1000 });
  assert.equal(await statusOf("pay_w3"), "failed");
  await hook({ id: "evt_w3b", type: "charge.succeeded", paymentId: "pay_w3", created: 1005 });
  assert.equal(await statusOf("pay_w3"), "paid");
  await hook({ id: "evt_w3c", type: "charge.failed", paymentId: "pay_w3", created: 1006 });
  assert.equal(await statusOf("pay_w3"), "paid");
});

test("webhook: the same event sent at once is applied once", async () => {
  await newOrder("pay_w4");
  const event = { id: "evt_w4", type: "charge.succeeded", paymentId: "pay_w4", created: 1000 };
  const results = await Promise.all(Array.from({ length: 15 }, async () => (await hook(event)).json()));
  assert.equal(results.filter((r) => r.applied === true).length, 1);
  assert.equal(await statusOf("pay_w4"), "paid");
});
EOF
